package io.github.jesterportfolio.hearth.survival.rpg;
import java.nio.file.*;import java.util.*;
import io.github.jesterportfolio.hearth.administration.RuntimeLease;
/** 사망당 표식 하나. 불명확한 결과는 HOLD하며 아이템을 자동 복원/재지급하지 않는다. */
public final class DeathJournal {
    private final Path directory;private final UUID group;private final Set<UUID> held=new HashSet<>();
    public DeathJournal(Path data,UUID group)throws Exception{this.group=group;directory=data.resolve("rpg-death-pending");if(!data.equals(data.toRealPath()))throw new IllegalStateException("DEATH_PATH");if(!Files.exists(directory,LinkOption.NOFOLLOW_LINKS))Files.createDirectory(directory);if(!directory.equals(directory.toRealPath()))throw new IllegalStateException("DEATH_PATH");try(var files=Files.list(directory)){for(var file:files.toList()){if(file.getFileName().toString().matches("[a-f0-9-]{36}\\.before")){if(!file.equals(file.toRealPath())||Files.size(file)>4194304)throw new IllegalStateException("DEATH_BEFORE_PATH");continue;}if(held.size()>=10000||!file.equals(file.toRealPath())||!file.getFileName().toString().matches("[a-f0-9-]{36}\\.pending")||Files.size(file)>1024)throw new IllegalStateException("DEATH_MARKER");var lines=Files.readAllLines(file);if(lines.size()<4||!lines.get(0).equals("Hearth death inventory v1")||!lines.get(1).equals(group.toString()))throw new IllegalStateException("DEATH_MARKER");held.add(UUID.fromString(file.getFileName().toString().substring(0,36)));}}}
    public boolean held(UUID player){return held.contains(player);}
    public final class Ticket {private final UUID player;private final RuntimeLease.Lease lease;private Ticket(UUID p,RuntimeLease.Lease l){player=p;lease=l;}public void clean()throws Exception{lease.clean();Files.deleteIfExists(directory.resolve(player+".before"));held.remove(player);}}
    public Ticket acquire(UUID player,String before,String after,org.bukkit.inventory.ItemStack[] original)throws Exception{if(held.contains(player)||!before.matches("[a-f0-9]{64}")||!after.matches("[a-f0-9]{64}"))throw new IllegalStateException("DEATH_HELD");var lease=RuntimeLease.acquire(directory.resolve(player+".pending"),"Hearth death inventory v1\n"+group+"\n"+before+"\n"+after+"\n").orElseThrow();held.add(player);Path payload=directory.resolve(player+".before");Files.createFile(payload,java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")));try(var out=new java.io.DataOutputStream(Files.newOutputStream(payload,StandardOpenOption.WRITE))){out.writeInt(1);out.writeInt(original.length);long size=8;for(var item:original){byte[] bytes=item==null||item.isEmpty()?new byte[0]:item.serializeAsBytes();size+=4+bytes.length;if(size>4194304)throw new IllegalStateException("DEATH_BEFORE_LIMIT");out.writeInt(bytes.length);out.write(bytes);}}try(var channel=java.nio.channels.FileChannel.open(payload,StandardOpenOption.WRITE)){channel.force(true);}return new Ticket(player,lease);}
}
